-- Client portal: users, sign-in with two-factor authentication, surveys and responses.
-- All ids are random UUIDs generated by the Worker. Times are ISO 8601 UTC strings.

CREATE TABLE IF NOT EXISTS companies (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_at  TEXT NOT NULL
);

-- One row per person. id is the user's UID. Roles combine (a CEO can be a respondent and a viewer).
CREATE TABLE IF NOT EXISTS users (
  id               TEXT PRIMARY KEY,
  email            TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name             TEXT NOT NULL,
  phone            TEXT NOT NULL,
  company_id       TEXT NOT NULL REFERENCES companies(id),
  lang             TEXT NOT NULL DEFAULT 'en',          -- en | he, used for links and the default interface
  is_admin         INTEGER NOT NULL DEFAULT 0,
  is_editor        INTEGER NOT NULL DEFAULT 0,
  is_viewer        INTEGER NOT NULL DEFAULT 0,          -- company-wide anonymized results
  is_respondent    INTEGER NOT NULL DEFAULT 0,          -- answers surveys assigned to them
  status           TEXT NOT NULL DEFAULT 'pending',     -- pending (no password yet) | active | disabled
  password_hash    TEXT,                                -- pbkdf2-sha256$iterations$salt$hash
  totp_secret      TEXT,                                -- base32; set once 2FA setup is confirmed
  totp_pending     TEXT,                                -- base32 secret offered during setup, not yet confirmed
  totp_last_step   INTEGER NOT NULL DEFAULT 0,          -- last accepted TOTP time step (blocks code reuse)
  failed_logins    INTEGER NOT NULL DEFAULT 0,
  locked_until     TEXT,
  last_login_at    TEXT,
  created_at       TEXT NOT NULL,
  created_by       TEXT
);
CREATE INDEX IF NOT EXISTS idx_users_company ON users (company_id);

-- Single-use links for first setup and admin password resets. Only a SHA-256 of the token is stored.
CREATE TABLE IF NOT EXISTS auth_tokens (
  token_hash  TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id),
  purpose     TEXT NOT NULL,                           -- setup | reset
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  used_at     TEXT,
  created_by  TEXT
);
CREATE INDEX IF NOT EXISTS idx_tokens_user ON auth_tokens (user_id);

-- Server-side sessions. The browser cookie holds the raw token; only its SHA-256 is stored.
CREATE TABLE IF NOT EXISTS sessions (
  id_hash      TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id),
  stage        TEXT NOT NULL,                          -- mfa (password ok, code pending) | setup (must finish password/2FA setup) | full
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions (user_id);

CREATE TABLE IF NOT EXISTS recovery_codes (
  user_id    TEXT NOT NULL REFERENCES users(id),
  code_hash  TEXT NOT NULL,
  used_at    TEXT,
  PRIMARY KEY (user_id, code_hash)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  at         TEXT NOT NULL,
  actor_id   TEXT,
  action     TEXT NOT NULL,
  target_id  TEXT,
  detail     TEXT
);
CREATE INDEX IF NOT EXISTS idx_audit_at ON audit_log (at);

-- ---------- Surveys ----------

CREATE TABLE IF NOT EXISTS surveys (
  id            TEXT PRIMARY KEY,
  company_id    TEXT NOT NULL REFERENCES companies(id),
  title_en      TEXT NOT NULL DEFAULT '',
  title_he      TEXT NOT NULL DEFAULT '',
  intro_en      TEXT NOT NULL DEFAULT '',
  intro_he      TEXT NOT NULL DEFAULT '',
  status        TEXT NOT NULL DEFAULT 'draft',         -- draft | open | closed
  closes_at     TEXT,                                  -- optional; responses stop being editable after this
  logo          BLOB,                                  -- customer logo (PNG, JPEG or WebP, max 256 KB)
  logo_type     TEXT,
  created_by    TEXT NOT NULL REFERENCES users(id),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_surveys_company ON surveys (company_id);

-- Editors invited to collaborate on a survey (the creator is not listed here).
CREATE TABLE IF NOT EXISTS survey_editors (
  survey_id  TEXT NOT NULL REFERENCES surveys(id) ON DELETE CASCADE,
  user_id    TEXT NOT NULL REFERENCES users(id),
  added_by   TEXT,
  added_at   TEXT NOT NULL,
  PRIMARY KEY (survey_id, user_id)
);

CREATE TABLE IF NOT EXISTS survey_sections (
  id          TEXT PRIMARY KEY,
  survey_id   TEXT NOT NULL REFERENCES surveys(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  title_en    TEXT NOT NULL DEFAULT '',
  title_he    TEXT NOT NULL DEFAULT '',
  intro_en    TEXT NOT NULL DEFAULT '',
  intro_he    TEXT NOT NULL DEFAULT '',
  capability  TEXT,                                    -- optional capability key used for scoring
  created_by  TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sections_survey ON survey_sections (survey_id, position);

-- config is JSON and depends on type (options, scale points, labels, grid rows, scoring role).
CREATE TABLE IF NOT EXISTS survey_questions (
  id          TEXT PRIMARY KEY,
  survey_id   TEXT NOT NULL REFERENCES surveys(id) ON DELETE CASCADE,
  section_id  TEXT NOT NULL REFERENCES survey_sections(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  type        TEXT NOT NULL,
  text_en     TEXT NOT NULL DEFAULT '',
  text_he     TEXT NOT NULL DEFAULT '',
  help_en     TEXT NOT NULL DEFAULT '',
  help_he     TEXT NOT NULL DEFAULT '',
  required    INTEGER NOT NULL DEFAULT 0,
  config      TEXT NOT NULL DEFAULT '{}',
  created_by  TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_questions_section ON survey_questions (section_id, position);

-- Who is asked to answer a survey. is_ceo marks the CEO for the CEO versus team comparison (xSim only).
CREATE TABLE IF NOT EXISTS survey_assignments (
  survey_id     TEXT NOT NULL REFERENCES surveys(id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users(id),
  is_ceo        INTEGER NOT NULL DEFAULT 0,
  assigned_at   TEXT NOT NULL,
  started_at    TEXT,
  submitted_at  TEXT,
  answer_lang   TEXT,
  PRIMARY KEY (survey_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_assign_user ON survey_assignments (user_id);

-- One row per answered question. value is JSON (number, string, array or object, depending on type).
CREATE TABLE IF NOT EXISTS survey_answers (
  survey_id    TEXT NOT NULL REFERENCES surveys(id) ON DELETE CASCADE,
  user_id      TEXT NOT NULL REFERENCES users(id),
  question_id  TEXT NOT NULL REFERENCES survey_questions(id) ON DELETE CASCADE,
  value        TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  PRIMARY KEY (survey_id, user_id, question_id)
);
CREATE INDEX IF NOT EXISTS idx_answers_question ON survey_answers (question_id);
